/**
 * music-loader.ts - 音乐加载模块
 *
 * 本模块负责从外部 CDN 加载音乐搜索库
 * 复用原有悬浮播放器的加载逻辑
 */

/**
 * 确保音乐库已加载
 * @returns Promise resolve 表示加载成功，reject 表示加载失败
 */
export function ensureMusicLoaded(): Promise<void> {
  if ((globalThis as any).Music) {
    return Promise.resolve();
  }

  return new Promise<void>((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://drive.baibai.cv/f/ZKEBuW/Music.js';
    s.onload = () => resolve();
    s.onerror = () => reject();
    document.head.appendChild(s);
  });
}
