Y,CACZ,YACF,CAEA,6BACE,UAAW,CACX,WACF,CACF","sourcesContent":["<template>\n  <div\n    id=\"vinylWidget\"\n    class=\"vinyl-widget\"\n    :class=\"{ expanded: isExpanded, dragging: isDragging }\"\n    :style=\"`top:${dragY};left:${dragX}`\"\n    @mousedown=\"startDrag\"\n    @touchstart=\"startDrag\"\n    @contextmenu=\"onContextMenu\"\n    @mouseenter=\"onMouseEnter\"\n    @mouseleave=\"onMouseLeave\"\n    @touchend=\"onTouchEnd\"\n    ref=\"widget\"\n  >\n    <!-- 悬浮球状态：黑胶唱片 -->\n    <div v-if=\"!isExpanded\" class=\"vinyl-ball\">\n      <div class=\"vinyl-record\" :class=\"{ spinning: isPlaying }\">\n        <div class=\"vinyl-center\"></div>\n        <div class=\"vinyl-ring ring-1\"></div>\n        <div class=\"vinyl-ring ring-2\"></div>\n        <div class=\"vinyl-ring ring-3\"></div>\n      </div>\n    </div>\n\n    <!-- 展开状态：随身听 -->\n    <div v-else class=\"player-body\" @click.stop>\n      <!-- 黑胶唱片区域 -->\n      <div class=\"disc-container\">\n        <div class=\"disc-arm\" :class=\"{ playing: isPlaying }\">\n          <div class=\"arm-base\"></div>\n          <div class=\"arm-stick\"></div>\n          <div class=\"arm-head\"></div>\n        </div>\n        <div class=\"disc\" :class=\"{ spinning: isPlaying }\">\n          <div class=\"disc-label\"></div>\n          <div class=\"disc-groove groove-1\"></div>\n          <div class=\"disc-groove groove-2\"></div>\n          <div class=\"disc-groove groove-3\"></div>\n          <div class=\"disc-groove groove-4\"></div>\n          <div class=\"disc-groove groove-5\"></div>\n        </div>\n      </div>\n\n      <!-- 歌曲信息 -->\n      <div class=\"song-info-section\">\n        <div class=\"song-name\">{{ currentSong || '等待播放...' }}</div>\n        <div class=\"song-singer\">{{ currentSinger || '未知歌手' }}</div>\n      </div>\n\n      <!-- 进度条 -->\n      <div class=\"progress-section\">\n        <span class=\"time-current\">{{ formatTime(currentTime) }}</span>\n        <div class=\"progress-bar-container\">\n          <input\n            type=\"range\"\n            class=\"progress-slider\"\n            min=\"0\"\n            :max=\"duration\"\n            v-model=\"currentTime\"\n            @input=\"onProgressChange\"\n            :style=\"{ '--progress-fill': progressPercent + '%' }\"\n          />\n        </div>\n        <span class=\"time-total\">{{ formatTime(duration) }}</span>\n      </div>\n\n      <!-- 控制按钮 -->\n      <div class=\"controls-section\">\n        <button class=\"ctrl-btn mode-btn\" :title=\"getModeTitle()\" @click=\"togglePlayMode\">\n          <i :class=\"getModeIcon()\"></i>\n        </button>\n        <button class=\"ctrl-btn prev-btn\" title=\"上一首\" @click=\"e => controlAction(e, 'prev')\">\n          <i class=\"fas fa-backward\"></i>\n        </button>\n        <button class=\"ctrl-btn play-btn\" :title=\"isPlaying ? '暂停' : '播放'\" @click=\"e => controlAction(e, isPlaying ? 'stop' : 'play')\">\n          <i :class=\"['fas', isPlaying ? 'fa-pause' : 'fa-play']\"></i>\n        </button>\n        <button class=\"ctrl-btn next-btn\" title=\"下一首\" @click=\"e => controlAction(e, 'next')\">\n          <i class=\"fas fa-forward\"></i>\n        </button>\n        <button class=\"ctrl-btn volume-btn\" title=\"音量\" @click=\"toggleVolume\">\n          <i :class=\"getVolumeIcon()\"></i>\n        </button>\n      </div>\n\n      <!-- 音量滑块（可折叠） -->\n      <div class=\"volume-section\" :class=\"{ visible: showVolume }\">\n        <i class=\"fas fa-volume-down vol-icon\"></i>\n        <input\n          type=\"range\"\n          class=\"volume-slider\"\n          min=\"0\"\n          max=\"100\"\n          v-model=\"volume\"\n          :style=\"{ '--volume-fill': volume + '%' }\"\n        />\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch, computed, onMounted, onBeforeUnmount } from 'vue';\nimport { sharedState } from './shared-state';\n\nconst Music = (globalThis as any).Music;\n\n// 播放状态\nconst isPlaying = ref(false);\nconst isExpanded = ref(false);\nconst currentSong = ref('');\nconst currentSinger = ref('');\nconst currentLyricStr = ref('');\nconst parsedLyrics = ref<{ time: number; text: string }[]>([]);\nconst currentLyricIndex = ref(-1);\nconst hasStarted = ref(false);\nconst playingIndex = ref(-1);\n\n// 音频\nconst musicAudio = new Audio();\n\n// 进度\nconst currentTime = ref(0);\nconst duration = ref(0);\n\n// 音量\nconst volume = ref(65);\nconst showVolume = ref(false);\n\n// 播放模式\ntype PlayMode = 'list' | 'single' | 'sequence' | 'random';\nconst playMode = ref<PlayMode>('list');\n\nmusicAudio.volume = volume.value / 100;\n\nwatch(volume, (newVal) => {\n  musicAudio.volume = newVal / 100;\n});\n\n// 进度百分比\nconst progressPercent = computed(() => {\n  if (duration.value === 0) return 0;\n  return (currentTime.value / duration.value) * 100;\n});\n\n// 监听 sharedState 变化\nwatch(\n  () => sharedState.music.index,\n  (newVal, oldVal) => {\n    console.log('index 变化:', oldVal, '->', newVal);\n    if (oldVal == -1 && newVal > -1) {\n      controlAction(null, 'play');\n    }\n  }\n);\n\n// 歌词解析\nfunction parseLyricToTimeline(lyric: string) {\n  const lines = lyric.split(/\\r?\\n/);\n  const entries: { time: number; text: string }[] = [];\n\n  for (const line of lines) {\n    const timeTags = line.match(/\\[(\\d{1,2}):(\\d{2})(?:\\.(\\d{1,3}))?\\]/g);\n    const text = line.replace(/\\[(\\d{1,2}):(\\d{2})(?:\\.(\\d{1,3}))?\\]/g, '').trim();\n    if (!timeTags || !text) continue;\n\n    for (const tag of timeTags) {\n      const match = tag.match(/\\[(\\d{1,2}):(\\d{2})(?:\\.(\\d{1,3}))?\\]/);\n      if (!match) continue;\n      const minutes = Number(match[1]);\n      const seconds = Number(match[2]);\n      const millis = match[3] ? Number(match[3].padEnd(3, '0')) : 0;\n      const time = minutes * 60 + seconds + millis / 1000;\n      entries.push({ time, text });\n    }\n  }\n\n  entries.sort((a, b) => a.time - b.time);\n  return entries;\n}\n\nfunction updateLyricDisplayByTime(time: number) {\n  const list = parsedLyrics.value;\n  if (!list.length) return;\n\n  let idx = list.length - 1;\n  for (let i = 0; i < list.length; i++) {\n    if (time < list[i].time) {\n      idx = i - 1;\n      break;\n    }\n  }\n\n  if (idx !== currentLyricIndex.value) {\n    currentLyricIndex.value = idx;\n  }\n}\n\nfunction onTimeUpdate() {\n  currentTime.value = musicAudio.currentTime || 0;\n  updateLyricDisplayByTime(currentTime.value);\n}\n\nfunction onLoadedMetadata() {\n  duration.value = musicAudio.duration || 0;\n}\n\nfunction onEnded() {\n  // 根据播放模式处理结束\n  let nextIndex = -1;\n\n  switch (playMode.value) {\n    case 'single':\n      // 单曲循环：重新播放当前\n      nextIndex = playingIndex.value;\n      break;\n    case 'list':\n      // 列表循环：下一首，循环到开头\n      if (playingIndex.value < sharedState.music.list.length - 1) {\n        nextIndex = playingIndex.value + 1;\n      } else {\n        nextIndex = 0;\n      }\n      break;\n    case 'sequence':\n      // 顺序播放：下一首，到末尾停止\n      if (playingIndex.value < sharedState.music.list.length - 1) {\n        nextIndex = playingIndex.value + 1;\n      } else {\n        isPlaying.value = false;\n        return;\n      }\n      break;\n    case 'random':\n      // 随机播放\n      nextIndex = Math.floor(Math.random() * sharedState.music.list.length);\n      break;\n  }\n\n  if (nextIndex >= 0 && nextIndex < sharedState.music.list.length) {\n    sharedState.music.index = nextIndex;\n    PlayMusic(nextIndex);\n  }\n}\n\n// 播放控制\nasync function controlAction(event: any, action: any) {\n  event?.stopPropagation();\n  startHideTimer();\n\n  if (action == 'stop') {\n    musicAudio.pause();\n    isPlaying.value = false;\n    return;\n  }\n\n  let index = sharedState.music.index;\n  if (index == -1) return;\n  if (index > sharedState.music.list.length - 1) {\n    index = sharedState.music.list.length - 1;\n    sharedState.music.index = index;\n  }\n\n  if (action == 'play') {\n    const canResume = hasStarted.value && playingIndex.value === index && musicAudio.src;\n    if (!isPlaying.value && canResume) {\n      musicAudio.play();\n      isPlaying.value = true;\n      return;\n    }\n    PlayMusic(index);\n  }\n\n  if (action == 'prev') {\n    if (playMode.value === 'random') {\n      index = Math.floor(Math.random() * sharedState.music.list.length);\n    } else if (index > 0) {\n      index -= 1;\n    } else {\n      index = sharedState.music.list.length - 1;\n    }\n    sharedState.music.index = index;\n    PlayMusic(index);\n  }\n\n  if (action == 'next') {\n    if (playMode.value === 'random') {\n      index = Math.floor(Math.random() * sharedState.music.list.length);\n    } else if (index == sharedState.music.list.length - 1) {\n      index = 0;\n    } else if (index < 0) {\n      index = 0;\n    } else {\n      index += 1;\n    }\n    sharedState.music.index = index;\n    PlayMusic(index);\n  }\n}\n\nasync function PlayMusic(index: number) {\n  const song = sharedState.music.list[index];\n  const name = song.song;\n  let playUrl = '';\n  const cached = sharedState.music.cache[name];\n  const cachedMeta = cached && typeof cached === 'object' ? cached : null;\n\n  if (cached) {\n    const cachedUrl = typeof cached === 'string' ? cached : cached.Url;\n    if (cachedUrl) {\n      const available = await sharedState.music.checkAudioAvailability(cachedUrl);\n      if (available) {\n        playUrl = cachedUrl;\n        if (cachedMeta) {\n          currentSinger.value = cachedMeta.Singer;\n          currentSong.value = cachedMeta.Name;\n          currentLyricStr.value = cachedMeta.Lyric;\n        }\n      }\n    }\n  }\n\n  let fetchedMeta: any = null;\n  if (!playUrl) {\n    const result = await Music.SearchMusic(name);\n    console.log(JSON.stringify(result));\n\n    if (!result?.Url) {\n      return;\n    }\n    playUrl = result.Url;\n    fetchedMeta = result;\n    sharedState.music.cache[name] = result;\n  }\n\n  if (playUrl != musicAudio.src) {\n    musicAudio.src = playUrl;\n  }\n\n  const meta = fetchedMeta || cachedMeta;\n  if (meta) {\n    currentSinger.value = meta.Singer;\n    currentSong.value = meta.Name;\n    currentLyricStr.value = meta.Lyric;\n  }\n\n  if (currentLyricStr.value) {\n    parsedLyrics.value = parseLyricToTimeline(currentLyricStr.value || '');\n    currentLyricIndex.value = -1;\n    updateLyricDisplayByTime(0);\n  }\n\n  await musicAudio.play();\n  isPlaying.value = true;\n  hasStarted.value = true;\n  playingIndex.value = index;\n}\n\n// 进度条变化\nfunction onProgressChange() {\n  musicAudio.currentTime = currentTime.value;\n}\n\n// 播放模式\nfunction togglePlayMode() {\n  const modes: PlayMode[] = ['list', 'single', 'sequence', 'random'];\n  const currentIdx = modes.indexOf(playMode.value);\n  playMode.value = modes[(currentIdx + 1) % modes.length];\n}\n\nfunction getModeIcon() {\n  switch (playMode.value) {\n    case 'list':\n      return 'fas fa-repeat';\n    case 'single':\n      return 'fas fa-repeat-1';\n    case 'sequence':\n      return 'fas fa-arrow-right';\n    case 'random':\n      return 'fas fa-shuffle';\n  }\n}\n\nfunction getModeTitle() {\n  switch (playMode.value) {\n    case 'list':\n      return '列表循环';\n    case 'single':\n      return '单曲循环';\n    case 'sequence':\n      return '顺序播放';\n    case 'random':\n      return '随机播放';\n  }\n}\n\n// 音量\nfunction toggleVolume() {\n  showVolume.value = !showVolume.value;\n}\n\nfunction getVolumeIcon() {\n  if (volume.value == 0) return 'fas fa-volume-mute';\n  if (volume.value < 50) return 'fas fa-volume-down';\n  return 'fas fa-volume-up';\n}\n\n// 时间格式化\nfunction formatTime(seconds: number): string {\n  if (!seconds || isNaN(seconds)) return '0:00';\n  const mins = Math.floor(seconds / 60);\n  const secs = Math.floor(seconds % 60);\n  return `${mins}:${secs.toString().padStart(2, '0')}`;\n}\n\n// ===== 拖拽实现 =====\nconst widget = ref<HTMLElement | null>(null);\nlet startX = 0,\n  startY = 0,\n  initialX = 0,\n  initialY = 0;\nconst dragX = ref('50%');\nconst dragY = ref('20%');\nlet hideTimer: any = null;\nconst isDragging = ref(false);\nconst hasMovedWhileDragging = ref(false);\nconst isRightClick = ref(false);\nconst windowWidth = $('body').width() || 0;\nconst windowHeight = $('body').height() || 0;\nconst isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);\n\nfunction startHideTimer() {\n  clearTimeout(hideTimer);\n  if (isExpanded.value) {\n    hideTimer = setTimeout(() => {\n      collapseWidget();\n    }, 3000);\n  }\n}\n\nfunction collapseWidget() {\n  if (!isDragging.value && !hasMovedWhileDragging.value) {\n    isExpanded.value = false;\n  }\n}\n\nfunction startDrag(e: any) {\n  const el = widget.value;\n  if (!el) return;\n\n  if (e.button === 2 || e.which === 3) {\n    isRightClick.value = true;\n    return;\n  }\n\n  if (isMobile && e.target && e.target.closest && e.target.closest('.controls-section')) {\n    if (isExpanded.value) {\n      clearTimeout(hideTimer);\n    }\n    return;\n  }\n\n  if (e.target.closest('.volume-section')) {\n    if (isExpanded.value) {\n      clearTimeout(hideTimer);\n    }\n    return;\n  }\n\n  if (isExpanded.value && e.target.closest('.disc-container')) {\n    clearTimeout(hideTimer);\n    return;\n  }\n\n  isRightClick.value = false;\n  isDragging.value = true;\n  hasMovedWhileDragging.value = false;\n  el.classList.add('dragging');\n\n  clearTimeout(hideTimer);\n\n  const rect = el.getBoundingClientRect();\n  initialX = rect.left + rect.width / 2;\n  initialY = rect.top + rect.height / 2;\n\n  if (e.type === 'mousedown') {\n    startX = e.clientX;\n    startY = e.clientY;\n    $('body').on('mousemove', drag);\n    $('body').on('mouseup', stopDrag);\n  } else if (e.type === 'touchstart') {\n    startX = e.touches[0].clientX;\n    startY = e.touches[0].clientY;\n    $('body').on('touchmove', drag);\n    $('body').on('touchend', stopDrag);\n  }\n}\n\nfunction drag(e: any) {\n  if (!isDragging.value || isRightClick.value) return;\n  if (e && typeof e.preventDefault === 'function') e.preventDefault();\n\n  hasMovedWhileDragging.value = true;\n\n  let clientX, clientY;\n  if (e.type === 'mousemove') {\n    clientX = e.clientX;\n    clientY = e.clientY;\n  } else if (e.type === 'touchmove') {\n    clientX = e.touches[0].clientX;\n    clientY = e.touches[0].clientY;\n  }\n\n  const deltaX = clientX - startX;\n  const deltaY = clientY - startY;\n\n  const newX = initialX + deltaX;\n  const newY = initialY + deltaY;\n\n  const margin = 20;\n  const maxX = windowWidth - margin;\n  const maxY = windowHeight - margin;\n\n  const clampedX = Math.max(margin, Math.min(maxX, newX));\n  const clampedY = Math.max(margin, Math.min(maxY, newY));\n\n  dragX.value = `${clampedX}px`;\n  dragY.value = `${clampedY}px`;\n}\n\nfunction stopDrag(e: any) {\n  if (!isDragging.value && !isRightClick.value) return;\n\n  $('body').off('mousemove', drag);\n  $('body').off('mouseup', stopDrag);\n  $('body').off('touchmove', drag);\n  $('body').off('touchend', stopDrag);\n\n  if (isRightClick.value) {\n    isRightClick.value = false;\n    return;\n  }\n\n  const el = widget.value;\n  isDragging.value = false;\n  el && el.classList.remove('dragging');\n\n  if (hasMovedWhileDragging.value) {\n    savePosition();\n    if (isExpanded.value) {\n      setTimeout(() => startHideTimer(), 100);\n    }\n  } else {\n    setTimeout(() => {\n      if (!isExpanded.value) {\n        expandWidget();\n      }\n    }, 50);\n  }\n\n  hasMovedWhileDragging.value = false;\n}\n\nfunction expandWidget() {\n  isExpanded.value = true;\n  startHideTimer();\n}\n\nfunction savePosition() {\n  const el = widget.value;\n  if (!el) return;\n  const rect = el.getBoundingClientRect();\n  const position = {\n    x: ((rect.left + rect.width / 2) / windowWidth) * 100,\n    y: ((rect.top + rect.height / 2) / windowHeight) * 100,\n  };\n  console.log(`保存坐标位置:\\n${JSON.stringify(position)}`);\n  localStorage.setItem('vinylPlayerPosition', JSON.stringify(position));\n}\n\nfunction restorePosition() {\n  const el = widget.value;\n  if (!el) return;\n  const saved = localStorage.getItem('vinylPlayerPosition');\n  console.log(`读取到的坐标位置:${saved}`);\n  if (saved) {\n    try {\n      const position = JSON.parse(saved);\n      let x = 50;\n      if (position.x < 100 && position.x > 0) {\n        x = position.x;\n      }\n      let y = 20;\n      if (position.y < 100 && position.y > 0) {\n        y = position.y;\n      }\n      dragX.value = x + '%';\n      dragY.value = y + '%';\n    } catch {\n      // 解析失败\n    }\n  }\n}\n\nfunction onContextMenu(e: any) {\n  const el = widget.value;\n  isRightClick.value = true;\n\n  if (isDragging.value) {\n    isDragging.value = false;\n    el && el.classList.remove('dragging');\n  }\n}\n\nfunction onMouseEnter() {\n  if (isMobile) return;\n  const el = widget.value;\n  if (isExpanded.value && !isDragging.value && !isRightClick.value) {\n    clearTimeout(hideTimer);\n  }\n}\n\nfunction onMouseLeave() {\n  if (isMobile) return;\n  const el = widget.value;\n  if (isExpanded.value && !isDragging.value && !isRightClick.value) {\n    clearTimeout(hideTimer);\n    hideTimer = setTimeout(() => {\n      collapseWidget();\n    }, 2000);\n  }\n}\n\nfunction onTouchEnd() {\n  if (!isMobile) return;\n  clearTimeout(hideTimer);\n  if (isExpanded.value && !isDragging.value) {\n    hideTimer = setTimeout(() => {\n      startHideTimer();\n    }, 100);\n  }\n}\n\nfunction onResize() {\n  const el = widget.value;\n  if (!el) return;\n  const rect = el.getBoundingClientRect();\n  const centerX = rect.left + rect.width / 2;\n  const centerY = rect.top + rect.height / 2;\n\n  const margin = 50;\n  const maxX = windowWidth - margin;\n  const maxY = windowHeight - margin;\n\n  const newX = Math.max(margin, Math.min(maxX, centerX));\n  const newY = Math.max(margin, Math.min(maxY, centerY));\n\n  dragX.value = (newX / windowWidth) * 100 + '%';\n  dragY.value = (newY / windowHeight) * 100 + '%';\n\n  savePosition();\n}\n\nfunction onVisibilityChange() {\n  if (document.hidden) {\n    clearTimeout(hideTimer);\n  } else if (isExpanded.value) {\n    startHideTimer();\n  }\n}\n\nfunction onDocumentClick(e: any) {\n  if (isRightClick.value && !(e.target && e.target.closest && e.target.closest('.vinyl-widget'))) {\n    isRightClick.value = false;\n  }\n}\n\nfunction onKeyDown(e: any) {\n  if (e.key === 'Escape') {\n    isRightClick.value = false;\n  }\n}\n\nonMounted(() => {\n  // 触摸移动\n  if (widget.value) {\n    widget.value.addEventListener(\n      'touchmove',\n      (e: TouchEvent) => {\n        if (isDragging.value && !isRightClick.value) {\n          e.preventDefault();\n        }\n      },\n      { passive: false }\n    );\n  }\n\n  $('body').on('visibilitychange', onVisibilityChange);\n  $('body').on('click', onDocumentClick);\n  $('body').on('keydown', onKeyDown);\n  window.addEventListener('resize', onResize);\n\n  restorePosition();\n\n  musicAudio.addEventListener('timeupdate', onTimeUpdate);\n  musicAudio.addEventListener('loadedmetadata', onLoadedMetadata);\n  musicAudio.addEventListener('ended', onEnded);\n});\n\nonBeforeUnmount(() => {\n  clearTimeout(hideTimer);\n  $('body').off('mousemove', drag);\n  $('body').off('mouseup', stopDrag);\n  $('body').off('touchmove', drag);\n  $('body').off('touchend', stopDrag);\n  $('body').off('visibilitychange', onVisibilityChange);\n  $('body').off('click', onDocumentClick);\n  $('body').off('keydown', onKeyDown);\n  window.removeEventListener('resize', onResize);\n  musicAudio.removeEventListener('timeupdate', onTimeUpdate);\n  musicAudio.removeEventListener('loadedmetadata', onLoadedMetadata);\n  musicAudio.removeEventListener('ended', onEnded);\n});\n</script>\n\n<style scoped>\n@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css');\n\n.vinyl-widget {\n  position: fixed;\n  top: 20%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  z-index: 9999999;\n  user-select: none;\n  cursor: pointer;\n  transition: all 0.3s ease;\n}\n\n.vinyl-widget.dragging {\n  cursor: grabbing;\n}\n\n/* ===== 悬浮球：黑胶唱片 ===== */\n.vinyl-ball {\n  width: 60px;\n  height: 60px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.vinyl-record {\n  width: 100%;\n  height: 100%;\n  border-radius: 50%;\n  background: #1a1a1a;\n  position: relative;\n  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.4);\n  animation: none;\n}\n\n.vinyl-record.spinning {\n  animation: spin 3s linear infinite;\n}\n\n@keyframes spin {\n  from { transform: rotate(0deg); }\n  to { transform: rotate(360deg); }\n}\n\n.vinyl-center {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  width: 14px;\n  height: 14px;\n  background: #333;\n  border-radius: 50%;\n  border: 2px solid #555;\n}\n\n.vinyl-ring {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  border-radius: 50%;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n}\n\n.ring-1 { width: 28px; height: 28px; }\n.ring-2 { width: 40px; height: 40px; }\n.ring-3 { width: 52px; height: 52px; }\n\n/* ===== 展开状态：随身听 ===== */\n.player-body {\n  width: 280px;\n  background: #ffffff;\n  border-radius: 20px;\n  padding: 20px;\n  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 16px;\n}\n\n/* 黑胶唱片容器 */\n.disc-container {\n  position: relative;\n  width: 160px;\n  height: 160px;\n}\n\n.disc {\n  width: 140px;\n  height: 140px;\n  border-radius: 50%;\n  background: #1a1a1a;\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);\n  animation: none;\n}\n\n.disc.spinning {\n  animation: spin 3s linear infinite;\n}\n\n.disc-label {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  width: 40px;\n  height: 40px;\n  background: #333;\n  border-radius: 50%;\n  border: 3px solid #555;\n}\n\n.disc-groove {\n  position: absolute;\n  top: 50%;\n  left