/**
 * shared-state.ts - 共享状态模块
 *
 * 本模块定义了播放器与酒馆之间共享的音乐状态，包括：
 * - 歌曲列表管理
 * - 当前播放索引
 * - 音频缓存
 * - 自动播放设置
 *
 * 复用原有悬浮播放器的核心逻辑
 */
import { reactive } from 'vue';

export const sharedState = reactive({
  music: {
    cache: {} as { [key: string]: any },
    regex: /<bgm>当前bgm[:：](.+?) - (.+?)<\/bgm>/g,
    list: [] as any[],
    index: -1,
    autoPlayer: false,

    async getAllChatMessages() {
      this.index = -1;
      const lastId = await triggerSlash('/pass {{lastMessageId}}');
      if (!lastId) {
        return;
      }
      const list = [];
      const ChatMessages = await getChatMessages(`0-${lastId}`, { role: 'all' });
      for (const message of ChatMessages) {
        const matches = [...message.message.matchAll(this.regex)];
        if (matches.length == 0) {
          continue;
        }

        // 取到多个格式,取最后一个
        const match = matches.at(-1)!;
        const obj = {
          song: match[1],
          singer: match[2],
          message_id: message.message_id,
        };

        list.push(obj);
      }
      this.list = list;

      console.log(this.list);
      if (list.length > 0) {
        this.index = list.length - 1;
      }
    },

    async checkAudioAvailability(url: string): Promise<boolean> {
      return new Promise(resolve => {
        const tester = new Audio();
        let timer: number;

        const onLoaded = () => {
          cleanup();
          resolve(true);
        };

        const onError = () => {
          cleanup();
          resolve(false);
        };

        const cleanup = () => {
          tester.removeEventListener('loadedmetadata', onLoaded);
          tester.removeEventListener('error', onError);
          clearTimeout(timer);
          tester.src = '';
        };

        tester.preload = 'metadata';
        tester.src = url;
        timer = setTimeout(onError, 3000) as unknown as number;

        tester.addEventListener('loadedmetadata', onLoaded);
        tester.addEventListener('error', onError);
      });
    },
  },
});
